                    .AsNoTracking()
                    .Where(x => x.CourseId == id)
                    .ProjectToType<CourseStudentDTO>(Mapper.CourseStudentProjectToConfig())
                    .ToListAsync();

                var result = new List<CourseStudentDTO>();

                foreach (var otherSideEntry in allOtherSideEntries)
