                    poco.Grade = dto.Grade.Value;
                    poco.Note = dto.Note;

                    var entry = await _deps.Context.DbSet<CourseStudent>().AddAsync(poco);

                    entry.Property("CourseId").CurrentValue = id;
                    entry.Property("StudentId").CurrentValue = dto.StudentId;
